function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['xoa sheet', 'delete sheet', 'xoa bang tinh'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

const spreadsheetId = source.spreadsheetId || source.sheetId || source.fileId || source.targetId || '';
const sheetName = cleanName(source.sheetName || source.fileName || body);

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    spreadsheetId,
    sheetName,
    hasTarget: Boolean(spreadsheetId || sheetName),
    response: (spreadsheetId || sheetName) ? '' : '🗑️ <b>Xoa Google Sheet</b>\n\nVi du: <code>xoa sheet Chi tieu</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, spreadsheetId: '', response: 'Khong tim thay Google Sheet phu hop.' } }];
}
const sheet = rows[0];
return [{ json: { ...source, spreadsheetId: sheet.id || source.spreadsheetId || '', sheetName: sheet.name || source.sheetName || '', webViewLink: sheet.webViewLink || '' } }];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};
const sheetId = item.id || source.spreadsheetId || '';
const sheetName = item.name || source.sheetName || 'Khong ro ten';
const link = item.webViewLink || source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Sheets delete response.');
}

let text = '🗑️ <b>Đã đưa Google Sheet vào thùng rác</b>\n\n';
text += `<b>${escapeHtml(sheetName)}</b>\n`;
if (sheetId) text += `ID: <code>${escapeHtml(sheetId)}</code>\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mở tài liệuh</a>`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
